/**
  * @brief  尝试获取单写者互斥锁 (USB U盘升级 vs USART2 串口升级)
  */
uint8_t boot_ota_acquire_writer(boot_writer_t writer)
{
  if (writer == BOOT_WRITER_NONE)
  {
    return 0U;
  }
  if (s_active_writer == BOOT_WRITER_NONE || s_active_writer == writer)
  {
    s_active_writer = writer;
    return 1U;
  }
  return 0U;
}

/**
  * @brief  释放单写者互斥锁
  */
void boot_ota_release_writer(boot_writer_t writer)
{
  if (s_active_writer == writer)
  {
    s_active_writer = BOOT_WRITER_NONE;
  }
}

/**
  * @brief  查询当前持有单写者互斥锁的通道
  */
boot_writer_t boot_ota_get_active_writer(void)
{
  return s_active_writer;
}

/**
  * @brief  生成动态非零 boot_id (基于 UID 寄存器与上电盐值)
  */
static uint32_t derive_dynamic_boot_id(void)
{
  s_boot_salt += 0x9E3779B9UL;
#ifndef HOST_UNIT_TEST
  uint32_t uid0 = *(volatile uint32_t *)0x1FFFF7E8UL;
  uint32_t uid1 = *(volatile uint32_t *)0x1FFFF7ECUL;
  }

  flash_lock();
  return 0;
}

/**
  * @brief  擦除前固件预验签门禁 (校验 ATSG 魔数、版本、Board ID、896KB 上限与 Trailer CRC32)
  */
static int verify_firmware_trailer(FIL *pfile, uint32_t filesize, uint32_t *p_payload_len)
{
  fw_trailer_t trailer;
  UINT bytes_read = 0;

  if (pfile == NULL || p_payload_len == NULL || filesize <= TRAILER_SIZE_BYTES)
  {
    printf("[PRE-VERIFY] Reject: File too small (%lu B, min > %u B)\r\n",
           filesize, TRAILER_SIZE_BYTES);
    return -1;
  }

  if (f_lseek(pfile, filesize - TRAILER_SIZE_BYTES) != FR_OK ||
      f_read(pfile, &trailer, sizeof(fw_trailer_t), &bytes_read) != FR_OK ||
      bytes_read != sizeof(fw_trailer_t))
  {
    printf("[PRE-VERIFY] Reject: Failed to read 128B trailer\r\n");
    return -1;
  }

  int rc = boot_verify_trailer_struct(&trailer, BOARD_ID_MC_AT32F435, MC_MAX_APP_SIZE);
  if (rc != 0)
  {
    printf("[PRE-VERIFY] REJECTED: Trailer check failed (rc=%d, magic=0x%08lX, board=0x%08lX)\r\n",
           rc, (unsigned long)trailer.magic, (unsigned long)trailer.board_id);
    return rc;
  }

  if (trailer.payload_len != (filesize - TRAILER_SIZE_BYTES))
  {
    printf("[PRE-VERIFY] Reject: Payload length mismatch (%lu != %lu)\r\n",
           trailer.payload_len, (filesize - TRAILER_SIZE_BYTES));
    return -3;
  }

  *p_payload_len = trailer.payload_len;
  printf("[PRE-VERIFY] PASS: MC Firmware verified. Payload: %lu B, Ver: 0x%08lX\r\n",
         trailer.payload_len, trailer.fw_version);
  return 0;
}

/**
  * @brief  擦除、写入并校验升级镜像 (擦除前预验签门禁保护)
  */
static int write_bin_to_flash(void)
{
  uint32_t base_addr = s_upgrade_bin.base_addr;
  uint32_t filesize = s_upgrade_bin.filesize;
  uint32_t payload_len = 0;

  if (f_open(&s_file, s_upgrade_bin.bin_name, FA_READ) != FR_OK)
  {
    printf("Failed to open %s\r\n", s_upgrade_bin.bin_name);
    return -1;
  }

  /* 擦除前预验签门禁: 严格校验 Magic, Board ID 与 Trailer */
  if (verify_firmware_trailer(&s_file, filesize, &payload_len) != 0)
  {
    f_close(&s_file);
    printf("[SECURITY GATE] Pre-verification FAILED. Flash erase ABORTED!\r\n");
    return -1;
  }

  if (base_addr < FLASH_APP_ADDR || (base_addr + payload_len) > FLASH_END_ADDR)
  {
    f_close(&s_file);
    printf("Invalid firmware memory range: 0x%08lX + 0x%08lX\r\n", base_addr, payload_len);
    return -1;
  }

  /* 仅擦除与写入有效净荷代码 (payload_len)，不污染 Flash 空间 */
  if (flash_erase_sectors(base_addr, payload_len) != 0 ||
      flash_write_image(&s_file, base_addr, payload_len) != 0)
  {
    f_close(&s_file);
    return -1;
  }

  uint32_t crc_flash = calculate_flash_crc(base_addr, payload_len);
  uint32_t crc_file = calculate_file_crc(&s_file, payload_len);
  f_close(&s_file);

  if (crc_flash != crc_file)
  {
    printf("CRC Check Mismatch! Flash: 0x%08lX, File: 0x%08lX\r\n", crc_flash, crc_file);
    return -1;
  }

  printf("CRC32 Check OK: 0x%08lX\r\n", crc_flash);
  return 0;
}
  /* 6. Check 2: 验证新文件存在且字节大小严格匹配 (若传入有效 expected_size) */
  if (f_stat(new_path, &fno) != FR_OK || (expected_size > 0U && fno.fsize != (FSIZE_t)expected_size))
  {
    printf("[BOOT] FS Check FAILED: %s stat mismatch (size=%lu, expect=%lu)\r\n",
           new_path, (uint32_t)fno.fsize, expected_size);
    return;
  }

  printf("[BOOT] FS Check PASSED: %s -> %s verified (Size=%lu B).\r\n",
         old_path, new_path, (uint32_t)fno.fsize);
}

static void handle_state_list_root(void)
{
  /* 仅在无合法 App 且无固件时停留在此状态，每隔 1000ms 输出提示 */
  if ((s_list_counter % 1000U) == 0U)
  {
    printf("No valid App at 0x%08X. Waiting for valid firmware in U-disk...\r\n", FLASH_APP_ADDR);
  }
  s_list_counter++;
}

static void handle_state_readlist(void)
{
  printf("Searching for upgrade package (%s)...\r\n", UPGRADE_BIN_NAME);
  if (find_upgrade_bin("0:/"))
  {
    if (boot_ota_acquire_writer(BOOT_WRITER_USB) == 0U)
    {
      printf("[BOOT] UART2 OTA active, deferring USB U-disk upgrade.\r\n");
      s_appstate = USER_IDEL;
      return;
    }
    printf("Found: %s, Size: %lu bytes, Target: 0x%08lX\r\n",
           s_upgrade_bin.bin_name, s_upgrade_bin.filesize, s_upgrade_bin.base_addr);
    g_upgrade_in_progress = 1;
    s_appstate = USER_WRITE;
    return;
  }

  printf("No valid upgrade package (%s) found on U-disk.\r\n", UPGRADE_BIN_NAME);

  /* 若处于串口驻留模式则保持驻留；否则若片内存在合法 App，立即注销文件系统并安全跳转运行 */
  if (boot_uart_ota_should_stay_in_boot() != 0U)
  {
    s_appstate = USER_IDEL;
  }
  else if (is_app_valid(FLASH_APP_ADDR))
  {
    f_mount(NULL, "0:/", 0);
    printf("[BOOT] No MC firmware. Valid App found at 0x%08X, jumping...\r\n", FLASH_APP_ADDR);
    jump_to_app(FLASH_APP_ADDR);
  }
  else
  {
    printf("[BOOT] Warning: No valid firmware on U-disk AND no valid App in Flash!\r\n");
    list_udisk_root_files();
    s_list_counter = 0;
    s_appstate = USER_LIST_ROOT;
  }
}

static void handle_state_write(void)
{
  printf("Starting firmware flash programming...\r\n");
  if (write_bin_to_flash() == 0)
  {
    g_upgrade_status = 1;
    printf("Upgrade %s successful!\r\n", s_upgrade_bin.bin_name);
    /* 升级成功：重命名为 .cur 并执行物理同步与 FS Check */
    rename_firmware_file(s_upgrade_bin.bin_name, "cur", s_upgrade_bin.filesize);
  }
  else
  {
    g_upgrade_status = 0;
    printf("Upgrade failed!\r\n");
    /* 升级失败：重命名为 .err，防止对损坏固件持续无限重试 */
    rename_firmware_file(s_upgrade_bin.bin_name, "err", 0U);
  }
  s_appstate = USER_IDEL;
}

static void handle_state_idle(void)
{
  f_mount(NULL, "0:/", 0);
  boot_ota_release_writer(BOOT_WRITER_USB);
  if (g_upgrade_status == 1)
  {
    printf("Jumping to Application at 0x%08X...\r\n", FLASH_APP_ADDR);
    jump_to_app(FLASH_APP_ADDR);
  }
  g_upgrade_in_progress = 0;
}

/**
  * @brief  USB Host 阶段状态机
  */
static usb_sts_type usbh_user_application(void)
{
  switch (s_appstate)
