/**\n+  * @brief  查询当前持有单写者互斥锁的通道\n+  */\n+boot_writer_t boot_ota_get_active_writer(void);\n+\n+/**\n+  * @brief  初始化 USART2 (PA2/PA3 @ 921600 8N1) 及 OTA 引擎，并检测 UPG2 驻留魔数\n+  */\n+void boot_uart_ota_init(void);\n+\n+/**\n+  * @brief  排空并复位关闭 USART2 外设 (跳转 App 前调用)\n+  */\n+void boot_uart_ota_deinit(void);\n+\n+/**\n+  * @brief  USART2 接收中断单字节推入环形队列\n+  */\n+void boot_uart_ota_rx_byte_isr(uint8_t byte);\n+\n+/**\n+  * @brief  主循环轮询解析 USART2 MiniMCProto v2.0 升级帧\n+  */\n+void boot_uart_ota_poll(void);\n+\n+/**\n+  * @brief  查询是否应驻留 Bootloader (收到 UPG2 魔数、0x1D 或 0x20 升级会话)\n+  */\n+uint8_t boot_uart_ota_should_stay_in_boot(void);\n+\n+/**\n+  * @brief  获取当前上电周期动态生成的 boot_id\n+  */\n+uint32_t boot_uart_ota_get_boot_id(void);\n+\n+/**\n+  * @brief  获取当前串口 OTA 上下文只读指针 (供单元测试与诊断使用)\n+  */\n+const mc_ota_ctx_t *boot_uart_ota_get_ctx(void);\n+\n+#ifdef __cplusplus\n+}\n+#endif\n+\n+#endif /* __BOOT_UART_OTA_H */\ndiff --git a/bootloader/src/boot_uart_ota.c b/bootloader/src/boot_uart_ota.c\nnew file mode 100644\nindex 0000000..61bf8fc\n--- /dev/null\n+++ b/bootloader/src/boot_uart_ota.c\n@@ -0,0 +1,828 @@\n+/**\n+  **************************************************************************\n+  * @file     boot_uart_ota.c\n+  * @brief    MC Bootloader (AT32F435) USART2 MiniMCProto v2.0 (Rev 2.0.4) OTA 与单写者仲裁实现\n+  **************************************************************************\n+  */\n+#ifndef BOOT_UART_OTA_C_INCLUDED\n+#define BOOT_UART_OTA_C_INCLUDED\n+\n+#include \"boot_uart_ota.h\"\n+#include \"usbh_user.h\"\n+#include <string.h>\n+#include <stdio.h>\n+\n+#ifndef HOST_UNIT_TEST\n+#include \"at32f435_437.h\"\n+#include \"at32f435_437_clock.h\"\n+#include \"at32f435_437_flash.h\"\n+#include \"at32f435_437_usart.h\"\n+#include \"at32f435_437_gpio.h\"\n+#include \"at32f435_437_crm.h\"\n+#include \"at32f435_437_misc.h\"\n+#else\n+/* Host 单元测试模拟桩声明 */\n+extern uint32_t host_mock_get_systick_ms(void);\n+extern int host_mock_flash_erase_sector(uint32_t sector_addr);\n+extern int host_mock_flash_write_bytes(uint32_t addr, const uint8_t *p_data, uint32_t len);\n+extern const uint8_t *host_mock_flash_ptr(uint32_t addr);\n+extern void host_mock_uart2_send_bytes(const uint8_t *p_data, uint16_t len);\n+extern uint32_t host_mock_read_magic(void);\n+extern void host_mock_write_magic(uint32_t val);\n+extern void host_mock_system_reset(void);\n+extern void host_mock_jump_to_app(uint32_t addr);\n+#endif\n+\n+#define UART2_TX_TIMEOUT_LOOPS          (200000U)\n+\n+/* 单写者互斥锁与串口环形队列静态存储 */\n+static volatile boot_writer_t s_active_writer = BOOT_WRITER_NONE;\n+static volatile uint8_t s_rx_ring[BOOT_UART2_RX_RING_SIZE];\n+static volatile uint16_t s_rx_head = 0U;\n+static volatile uint16_t s_rx_tail = 0U;\n+\n+/* 帧解析与发送静态缓冲 */\n+static uint8_t s_frame_buf[MINIMC_MAX_FRAME_SIZE];\n+static uint16_t s_frame_idx = 0U;\n+static uint16_t s_expected_frame_len = 0U;\n+static uint8_t s_tx_buf[MINIMC_MAX_FRAME_SIZE];\n+static uint32_t s_boot_salt = 0U;\n+static mc_ota_ctx_t s_ota;\n+\n+/**\n+  * @brief  计算标准 IEEE 802.3 CRC32 (Poly=0xEDB88320, Init=0xFFFFFFFF)\n+  */\n+uint32_t boot_crc32_ieee(const uint8_t *p_data, uint32_t length)\n+{\n+  if (p_data == NULL && length > 0U)\n+  {\n+    return 0U;\n+  }\n+\n+  uint32_t crc = 0xFFFFFFFFUL;\n+  for (uint32_t i = 0U; i < length; i++)\n+  {\n+    crc ^= (uint32_t)p_data[i];\n+    for (uint8_t bit = 0U; bit < 8U; bit++)\n+    {\n+      if ((crc & 1UL) != 0UL)\n+      {\n+        crc = (crc >> 1U) ^ 0xEDB88320UL;\n+      }\n+      else\n+      {\n+        crc >>= 1U;\n+      }\n+    }\n+  }\n+  return ~crc;\n+}\n+\n+/**\n+  * @brief  计算 CRC16-CCITT (Poly=0x1021, Init=0xFFFF)\n+  */\n+uint16_t boot_crc16_ccitt(const uint8_t *p_data, uint32_t length)\n+{\n+  if (p_data == NULL && length > 0U)\n+  {\n+    return 0U;\n+  }\n+\n+  uint16_t crc = 0xFFFFU;\n+  for (uint32_t i = 0U; i < length; i++)\n+  {\n+    crc ^= (uint16_t)((uint16_t)p_data[i] << 8U);\n+    for (uint8_t bit = 0U; bit < 8U; bit++)\n+    {\n+      if ((crc & 0x8000U) != 0U)\n+      {\n+        crc = (uint16_t)((crc << 1U) ^ 0x1021U);\n+      }\n+      else\n+      {\n+        crc = (uint16_t)(crc << 1U);\n+      }\n+    }\n+  }\n+  return crc;\n+}\n+\n+/**\n+  * @brief  校验 128 字节 ATSG Trailer 结构体合法性 (魔数、版本、Board ID、净荷上限与自身 CRC32)\n+  */\n+int boot_verify_trailer_struct(const fw_trailer_t *p_trailer,\n+                               uint32_t expected_board_id,\n+                               uint32_t max_payload_len)\n+{\n+  if (p_trailer == NULL)\n+  {\n+    return -1;\n+  }\n+  if (p_trailer->magic != TRAILER_MAGIC_ATSG)\n+  {\n+    return -2;\n+  }\n+  if (p_trailer->struct_ver != TRAILER_STRUCT_VER_V1)\n+  {\n+    return -3;\n+  }\n+  if (p_trailer->board_id != expected_board_id)\n+  {\n+    return -4;\n+  }\n+  if (p_trailer->payload_len == 0U || p_trailer->payload_len > max_payload_len)\n+  {\n+    return -5;\n+  }\n+\n+  uint32_t calc_crc = boot_crc32_ieee((const uint8_t *)p_trailer, TRAILER_HEADER_CRC_SIZE);\n+  if (calc_crc != p_trailer->trailer_crc32)\n+  {\n+    return -6;\n+  }\n+  return 0;\n+}\n+\n+/**\n+  * @brief  尝试获取单写者互斥锁 (USB U盘升级 vs USART2 串口升级)\n+  */\n+uint8_t boot_ota_acquire_writer(boot_writer_t writer)\n+{\n+  if (writer == BOOT_WRITER_NONE)\n+  {\n+    return 0U;\n+  }\n+  if (s_active_writer == BOOT_WRITER_NONE || s_active_writer == writer)\n+  {\n+    s_active_writer = writer;\n+    return 1U;\n+  }\n+  return 0U;\n+}\n+\n+/**\n+  * @brief  释放单写者互斥锁\n+  */\n+void boot_ota_release_writer(boot_writer_t writer)\n+{\n+  if (s_active_writer == writer)\n+  {\n+    s_active_writer = BOOT_WRITER_NONE;\n+  }\n+}\n+\n+/**\n+  * @brief  查询当前持有单写者互斥锁的通道\n+  */\n+boot_writer_t boot_ota_get_active_writer(void)\n+{\n+  return s_active_writer;\n+}\n+\n+/**\n+  * @brief  生成动态非零 boot_id (基于 UID 寄存器与上电盐值)\n+  */\n+static uint32_t derive_dynamic_boot_id(void)\n+{\n+  s_boot_salt += 0x9E3779B9UL;\n+#ifndef HOST_UNIT_TEST\n+  uint32_t uid0 = *(volatile uint32_t *)0x1FFFF7E8UL;\n+  uint32_t uid1 = *(volatile uint32_t *)0x1FFFF7ECUL;\n+  uint32_t uid2 = *(volatile uint32_t *)0x1FFFF7F0UL;\n+  uint32_t rst = CRM->ctrlsts;\n+  uint32_t id = uid0 ^ ((uid1 << 7U) | (uid1 >> 25U)) ^ uid2 ^ rst ^ s_boot_salt;\n+#else\n+  uint32_t id = 0x4350A55AUL ^ s_boot_salt;\n+#endif\n+  if (id == 0UL)\n+  {\n+    id = 0x43500001UL;\n+  }\n+  return id;\n+}\n+\n+/**\n+  * @brief  通过 USART2 发送指定长度字节流 (带超时保护)\n+  */\n+static void uart2_send_raw(const uint8_t *p_buf, uint16_t len)\n+{\n+  if (p_buf == NULL || len == 0U)\n+  {\n+    return;\n+  }\n+#ifndef HOST_UNIT_TEST\n+  for (uint16_t i = 0U; i < len; i++)\n+  {\n+    uint32_t timeout = UART2_TX_TIMEOUT_LOOPS;\n+    while (usart_flag_get(USART2, USART_TDBE_FLAG) == RESET && timeout > 0U)\n+    {\n+      timeout--;\n+    }\n+    usart_data_transmit(USART2, (uint16_t)p_buf[i]);\n+  }\n+  uint32_t tdc_timeout = UART2_TX_TIMEOUT_LOOPS;\n+  while (usart_flag_get(USART2, USART_TDC_FLAG) == RESET && tdc_timeout > 0U)\n+  {\n+    tdc_timeout--;\n+  }\n+#else\n+  host_mock_uart2_send_bytes(p_buf, len);\n+#endif\n+}\n+\n+/**\n+  * @brief  组装并通过 USART2 发送一帧 MiniMCProto v2.0 响应 (MC -> AP)\n+  */\n+static void send_minimc_response(const minimc_frame_hdr_t *p_req,\n+                                 uint8_t rsp_cmd,\n+                                 const uint8_t *p_payload,\n+                                 uint16_t payload_len)\n+{\n+  if (p_req == NULL || payload_len > MINIMC_MAX_PAYLOAD_SIZE)\n+  {\n+    return;\n+  }\n+\n+  minimc_frame_hdr_t hdr;\n+  hdr.sof0 = MINIMC_SOF_0;\n+  hdr.sof1 = MINIMC_SOF_1;\n+  hdr.src_id = MINIMC_NODE_MC;\n+  hdr.dst_id = p_req->src_id;\n+  hdr.flags = (uint8_t)(MINIMC_FLAG_VERSION_V2 | MINIMC_FLAG_IS_RESPONSE);\n+  hdr.cmd_id = rsp_cmd;\n+  hdr.hop_limit = MINIMC_DEFAULT_HOP_LIMIT;\n+  hdr.route_ctrl = 0U;\n+  hdr.seq_id = p_req->seq_id;\n+  hdr.payload_len = payload_len;\n+\n+  memcpy(s_tx_buf, &hdr, MINIMC_HEADER_SIZE);\n+  if (payload_len > 0U && p_payload != NULL)\n+  {\n+    memcpy(&s_tx_buf[MINIMC_HEADER_SIZE], p_payload, payload_len);\n+  }\n+\n+  uint16_t crc_pos = (uint16_t)(MINIMC_HEADER_SIZE + payload_len);\n+  uint16_t crc = boot_crc16_ccitt(s_tx_buf, crc_pos);\n+  s_tx_buf[crc_pos] = (uint8_t)(crc & 0xFFU);\n+  s_tx_buf[crc_pos + 1U] = (uint8_t)((crc >> 8U) & 0xFFU);\n+\n+  uart2_send_raw(s_tx_buf, (uint16_t)(crc_pos + MINIMC_CRC_SIZE));\n+}\n+\n+/**\n+  * @brief  发送标准 4 字节 0x00 CMD_ACK 应答帧\n+  */\n+static void send_ack(const minimc_frame_hdr_t *p_req)\n+{\n+  minimc_payload_ack_t ack;\n+  ack.planner_buf_free = 16U;\n+  ack.rx_fifo_free_units = 2U;\n+  ack.reserved = 0U;\n+  send_minimc_response(p_req, MINIMC_CMD_ACK, (const uint8_t *)&ack, sizeof(ack));\n+}\n+\n+/**\n+  * @brief  发送标准 3 字节 0x06 CMD_NACK 错误应答帧\n+  */\n+static void send_nack(const minimc_frame_hdr_t *p_req, uint8_t err_code)\n+{\n+  s_ota.last_error = err_code;\n+  minimc_payload_nack_t nack;\n+  nack.error_code = err_code;\n+  nack.expected_seq = p_req->seq_id;\n+  send_minimc_response(p_req, MINIMC_CMD_NACK, (const uint8_t *)&nack, sizeof(nack));\n+}\n+\n+/**\n+  * @brief  处理 0x01 CMD_GET_VERSION 请求并回复 16B 0x02 CMD_VERSION_REPORT\n+  */\n+static void handle_cmd_get_version(const minimc_frame_hdr_t *p_req)\n+{\n+  if (p_req->payload_len != 0U)\n+  {\n+    send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);\n+    return;\n+  }\n+  s_ota.stay_in_boot = 1U;\n+  minimc_payload_version_report_t rep;\n+  rep.proto_major = 2U;\n+  rep.proto_minor = 0U;\n+  rep.fw_major = 1U;\n+  rep.fw_minor = 0U;\n+  rep.boot_id = s_ota.boot_id;\n+  rep.git_commit_short = MC_FW_GIT_COMMIT_SHORT;\n+  rep.capability_flags = MC_BOOT_CAPABILITY_FLAGS;\n+  send_minimc_response(p_req, MINIMC_CMD_VERSION_REPORT, (const uint8_t *)&rep, sizeof(rep));\n+}\n+\n+/**\n+  * @brief  处理 0x03 CMD_PING 请求并回复 12B 0x04 CMD_PONG\n+  */\n+static void handle_cmd_ping(const minimc_frame_hdr_t *p_req, const uint8_t *p_payload)\n+{\n+  if (p_req->payload_len != 4U || p_payload == NULL)\n+  {\n+    send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);\n+    return;\n+  }\n+  minimc_payload_pong_t pong;\n+  memcpy(&pong.echo_token, p_payload, 4U);\n+#ifndef HOST_UNIT_TEST\n+  pong.uptime_ms = get_systick_ms();\n+#else\n+  pong.uptime_ms = host_mock_get_systick_ms();\n+#endif\n+  pong.rx_ok_count = s_ota.rx_ok_count;\n+  pong.rx_crc_err_count = s_ota.rx_crc_err_count;\n+  send_minimc_response(p_req, MINIMC_CMD_PONG, (const uint8_t *)&pong, sizeof(pong));\n+}\n+\n+/**\n+  * @brief  处理 0x1D CMD_SYSTEM_CONTROL (action: 1=Reboot, 2=JumpToBootloader)\n+  */\n+static void handle_cmd_system_control(const minimc_frame_hdr_t *p_req,\n+                                      const uint8_t *p_payload)\n+{\n+  if (p_payload == NULL || p_req->payload_len != sizeof(minimc_payload_sys_ctrl_t))\n+  {\n+    send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);\n+    return;\n+  }\n+\n+  minimc_payload_sys_ctrl_t ctrl;\n+  memcpy(&ctrl, p_payload, sizeof(ctrl));\n+  if (ctrl.action == 2U)\n+  {\n+    s_ota.stay_in_boot = 1U;\n+    send_ack(p_req);\n+  }\n+  else if (ctrl.action == 1U)\n+  {\n+    send_ack(p_req);\n+    s_ota.pending_reboot = 1U;\n+  }\n+  else\n+  {\n+    send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);\n+  }\n+}\n+\n+/**\n+  * @brief  处理 0x20 CMD_OTA_START (144B 擦除前 ATSG 准入校验与单写者加锁)\n+  */\n+static void handle_cmd_ota_start(const minimc_frame_hdr_t *p_req,\n+                                 const uint8_t *p_payload)\n+{\n+  if (g_upgrade_in_progress != 0U || boot_ota_acquire_writer(BOOT_WRITER_UART2) == 0U)\n+  {\n+    send_nack(p_req, MINIMC_ERR_DEVICE_BUSY);\n+    return;\n+  }\n+\n+  if (p_payload == NULL || p_req->payload_len != sizeof(minimc_payload_ota_start_t))\n+  {\n+    boot_ota_release_writer(BOOT_WRITER_UART2);\n+    send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);\n+    return;\n+  }\n+\n+  minimc_payload_ota_start_t req;\n+  memcpy(&req, p_payload, sizeof(req));\n+  if (req.fw_size_bytes > MC_MAX_APP_SIZE || req.trailer.payload_len > MC_MAX_APP_SIZE)\n+  {\n+    boot_ota_release_writer(BOOT_WRITER_UART2);\n+    send_nack(p_req, MINIMC_ERR_OTA_IMAGE_OVERSIZE);\n+    return;\n+  }\n+  if (req.target_device != MINIMC_NODE_MC ||\n+      req.fw_size_bytes == 0U ||\n+      req.fw_size_bytes != req.trailer.payload_len ||\n+      boot_verify_trailer_struct(&req.trailer, BOARD_ID_MC_AT32F435, MC_MAX_APP_SIZE) != 0)\n+  {\n+    boot_ota_release_writer(BOOT_WRITER_UART2);\n+    send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);\n+    return;\n+  }\n+\n+  s_ota.stay_in_boot = 1U;\n+  s_ota.state = MC_OTA_STATE_ERASED_READY;\n+  s_ota.last_error = 0U;\n+  s_ota.expected_size = req.fw_size_bytes;\n+  s_ota.expected_crc32 = req.fw_crc32;\n+  s_ota.next_offset = 0U;\n+  s_ota.erased_end_addr = FLASH_APP_ADDR;\n+  send_ack(p_req);\n+}\n+\n+/**\n+  * @brief  按需擦除 2KB 扇区并向 MC App 分区写入与回读校验数据块\n+  */\n+static int write_mc_app_flash_chunk(uint32_t offset,\n+                                    const uint8_t *p_data,\n+                                    uint32_t data_len)\n+{\n+  uint32_t target_addr = FLASH_APP_ADDR + offset;\n+  uint32_t end_addr = target_addr + data_len;\n+\n+#ifndef HOST_UNIT_TEST\n+  flash_unlock();\n+  while (s_ota.erased_end_addr < end_addr)\n+  {\n+    if (flash_sector_erase(s_ota.erased_end_addr) != FLASH_OPERATE_DONE)\n+    {\n+      flash_lock();\n+      return -1;\n+    }\n+    s_ota.erased_end_addr += MC_FLASH_SECTOR_SIZE;\n+  }\n+  for (uint32_t i = 0U; i < data_len; i++)\n+  {\n+    if (flash_byte_program(target_addr + i, p_data[i]) != FLASH_OPERATE_DONE ||\n+        *(volatile uint8_t *)(target_addr + i) != p_data[i])\n+    {\n+      flash_lock();\n+      return -2;\n+    }\n+  }\n+  flash_lock();\n+  return 0;\n+#else\n+  while (s_ota.erased_end_addr < end_addr)\n+  {\n+    if (host_mock_flash_erase_sector(s_ota.erased_end_addr) != 0)\n+    {\n+      return -1;\n+    }\n+    s_ota.erased_end_addr += MC_FLASH_SECTOR_SIZE;\n+  }\n+  return host_mock_flash_write_bytes(target_addr, p_data, data_len);\n+#endif\n+}\n+\n+/**\n+  * @brief  校验 0x21 CMD_OTA_DATA 的块长度、偏移边界与内层 CRC16\n+  */\n+static uint8_t validate_ota_data_bounds(const minimc_frame_hdr_t *p_req,\n+                                        const uint8_t *p_payload,\n+                                        minimc_payload_ota_data_hdr_t *p_dh)\n+{\n+  if (s_ota.state != MC_OTA_STATE_ERASED_READY && s_ota.state != MC_OTA_STATE_FLASH_WRITING)\n+  {\n+    return MINIMC_ERR_COMMAND_REJECTED;\n+  }\n+  if (p_payload == NULL || p_req->payload_len <= sizeof(minimc_payload_ota_data_hdr_t))\n+  {\n+    return MINIMC_ERR_COMMAND_REJECTED;\n+  }\n+  memcpy(p_dh, p_payload, sizeof(*p_dh));\n+  uint16_t data_len = (uint16_t)(p_req->payload_len - sizeof(*p_dh));\n+  if (p_dh->chunk_bytes == 0U || p_dh->chunk_bytes > CHUNK_MAX_SIZE || p_dh->chunk_bytes != data_len)\n+  {\n+    return MINIMC_ERR_MTU_EXCEEDED;\n+  }\n+  if (p_dh->offset > s_ota.expected_size || (uint32_t)data_len > (s_ota.expected_size - p_dh->offset))\n+  {\n+    return MINIMC_ERR_OTA_INVALID_OFFSET;\n+  }\n+  const uint8_t *p_data = &p_payload[sizeof(*p_dh)];\n+  if (boot_crc16_ccitt(p_data, data_len) != p_dh->chunk_crc16)\n+  {\n+    return MINIMC_ERR_CRC_FAIL;\n+  }\n+  return 0U;\n+}\n+\n+/**\n+  * @brief  处理 0x21 CMD_OTA_DATA (支持重传幂等与按扇区擦写回读校验)\n+  */\n+static void handle_cmd_ota_data(const minimc_frame_hdr_t *p_req,\n+                                const uint8_t *p_payload)\n+{\n+  minimc_payload_ota_data_hdr_t dh;\n+  uint8_t err = validate_ota_data_bounds(p_req, p_payload, &dh);\n+  if (err != 0U)\n+  {\n+    send_nack(p_req, err);\n+    return;\n+  }\n+\n+  /* 重传幂等：已写入块重传直接回复 ACK */\n+  if (dh.offset < s_ota.next_offset && (dh.offset + dh.chunk_bytes) <= s_ota.next_offset)\n+  {\n+    send_ack(p_req);\n+    return;\n+  }\n+  if (dh.offset != s_ota.next_offset)\n+  {\n+    send_nack(p_req, MINIMC_ERR_OTA_INVALID_OFFSET);\n+    return;\n+  }\n+\n+  const uint8_t *p_data = &p_payload[sizeof(dh)];\n+  int wrc = write_mc_app_flash_chunk(dh.offset, p_data, dh.chunk_bytes);\n+  if (wrc != 0)\n+  {\n+    s_ota.state = MC_OTA_ST