x 0000000..32e5493\n--- /dev/null\n+++ b/tests/run_tests.sh\n@@ -0,0 +1,99 @@\n+#!/bin/sh\n+# TWIN-63 MC Bootloader 交叉编译、打包边界与主机单元测试脚本\n+set -eu\n+\n+echo \"=== [1/4] Cross-compile MC Bootloader & verify 128KB Flash budget + zero USART6 coupling ===\"\n+make clean all\n+BIN_SIZE=$(stat -c%s build/bootloader.bin)\n+echo \"bootloader.bin size: ${BIN_SIZE} bytes (limit: 131072 bytes)\"\n+test \"${BIN_SIZE}\" -le 131072\n+if arm-none-eabi-nm build/bootloader.elf | grep -v \" W \" | grep -i \"usart6\"; then\n+  echo \"[FAIL] Non-weak USART6 symbol found in MC Bootloader ELF!\"\n+  exit 1\n+fi\n+if grep -rn \"USART6\" bootloader/src/ bootloader/inc/; then\n+  echo \"[FAIL] USART6 reference found in MC Bootloader source/headers!\"\n+  exit 1\n+fi\n+echo \"[PASS] Cross-compile <=128KB and zero USART6 coupling verified!\"\n+\n+echo \"=== [2/4] Verify scripts/pack_firmware.py MC (896KB=917,504B) & TH (236KB=241,664B) boundary gate ===\"\n+python3 - <<'PY'\n+import subprocess, sys, tempfile\n+from pathlib import Path\n+\n+with tempfile.TemporaryDirectory() as tmp:\n+    tdir = Path(tmp)\n+    # MC 正例: 917504B (896KB)\n+    mc_ok = tdir / \"mc_ok.bin\"\n+    mc_ok.write_bytes(b\"\\xAA\" * 917504)\n+    r1 = subprocess.run([sys.executable, \"scripts/pack_firmware.py\", \"-i\", str(mc_ok), \"-b\", \"0x43500001\", \"-o\", str(tdir / \"fw_mc.bin\")])\n+    assert r1.returncode == 0 and (tdir / \"fw_mc.bin\").stat().st_size == 917504 + 128\n+\n+    # MC 负例: 917505B (896KB + 1B) 必须失败\n+    mc_over = tdir / \"mc_over.bin\"\n+    mc_over.write_bytes(b\"\\xAA\" * 917505)\n+    r2 = subprocess.run([sys.executable, \"scripts/pack_firmware.py\", \"-i\", str(mc_over), \"-b\", \"0x43500001\", \"-o\", str(tdir / \"fw_mc_over.bin\")])\n+    assert r2.returncode != 0\n+\n+    # TH 正例: 241664B (236KB)\n+    th_ok = tdir / \"th_ok.bin\"\n+    th_ok.write_bytes(b\"\\x55\" * 241664)\n+    r3 = subprocess.run([sys.executable, \"scripts/pack_firmware.py\", \"-i\", str(th_ok), \"-b\", \"0x42300001\", \"-o\", str(tdir / \"fw_th.bin\")])\n+    assert r3.returncode == 0 and (tdir / \"fw_th.bin\").stat().st_size == 241664 + 128\n+\n+    # TH 负例: 241665B (236KB + 1B) 必须失败\n+    th_over = tdir / \"th_over.bin\"\n+    th_over.write_bytes(b\"\\x55\" * 241665)\n+    r4 = subprocess.run([sys.executable, \"scripts/pack_firmware.py\", \"-i\", str(th_over), \"-b\", \"0x42300001\", \"-o\", str(tdir / \"fw_th_over.bin\")])\n+    assert r4.returncode != 0\n+print(\"[PASS] scripts/pack_firmware.py MC(896KB) & TH(236KB) boundary checks passed!\")\n+PY\n+\n+echo \"=== [3/4] Compile & run host unit tests for MC Bootloader MiniMCProto v2.0 OTA ===\"\n+gcc -O2 -g3 -Wall -Wextra -Werror -DHOST_UNIT_TEST \\\n+    -Ibootloader/inc \\\n+    tests/test_mc_boot_ota.c \\\n+    -o build/test_mc_boot_ota\n+./build/test_mc_boot_ota\n+\n+echo \"=== [4/4] Verify C function length (<=50 lines) and parameter count (<=4) gate ===\"\n+python3 - <<'PY'\n+import re, sys\n+from pathlib import Path\n+\n+files = [\n+    Path(\"bootloader/src/boot_uart_ota.c\"),\n+    Path(\"bootloader/src/main.c\"),\n+    Path(\"bootloader/src/bsp_uart.c\"),\n+    Path(\"tests/test_mc_boot_ota.c\"),\n+]\n+\n+func_hdr = re.compile(r'^[A-Za-z_][\\w\\s\\*]*?\\b([A-Za-z_]\\w*)\\s*\\(([^;{}]*)\\)\\s*\\{', re.M)\n+for p in files:\n+    text = p.read_text(encoding=\"utf-8\")\n+    for m in func_hdr.finditer(text):\n+        name = m.group(1)\n+        if name in (\"if\", \"while\", \"for\", \"switch\"):\n+            continue\n+        params_raw = m.group(2).strip()\n+        params = [] if params_raw in (\"\", \"void\") else [x.strip() for x in params_raw.split(\",\")]\n+        brace_start = text.find(\"{\", m.start())\n+        depth = 0\n+        end_idx = brace_start\n+        for idx in range(brace_start, len(text)):\n+            if text[idx] == \"{\":\n+                depth += 1\n+            elif text[idx] == \"}\":\n+                depth -= 1\n+                if depth == 0:\n+                    end_idx = idx\n+                    break\n+        start_line = text.count(\"\\n\", 0, m.start()) + 1\n+        end_line = text.count(\"\\n\", 0, end_idx) + 1\n+        n_lines = end_line - start_line + 1\n+        if n_lines > 50 or len(params) > 4:\n+            print(f\"[FAIL] {p}:{name} lines={n_lines} params={len(params)}\")\n+            sys.exit(1)\n+print(\"[PASS] All checked C functions satisfy <=50 lines and <=4 parameters!\")\n+PY\ndiff --git a/tests/test_mc_boot_ota.c b/tests/test_mc_boot_ota.c\nnew file mode 100644\nindex 0000000..dfb157a\n--- /dev/null\n+++ b/tests/test_mc_boot_ota.c\n@@ -0,0 +1,421 @@\n+/**\n+  **************************************************************************\n+  * @file     test_mc_boot_ota.c\n+  * @brief    MC Bootloader (AT32F435) USART2 MiniMCProto v2.0 (Rev 2.0.4) 单元测试套件\n+  **************************************************************************\n+  */\n+#include <stdio.h>\n+#include <stdlib.h>\n+#include <stdint.h>\n+#include <string.h>\n+\n+/* 模拟 usbh_user.h 所需最小声明以隔离 USB Host 依赖 */\n+#define __USBH_USER_H\n+#define FLASH_APP_ADDR            (0x08020000U)\n+volatile uint8_t g_udisk_connected = 0U;\n+volatile uint8_t g_upgrade_in_progress = 0U;\n+volatile uint8_t g_upgrade_status = 0U;\n+uint8_t is_app_valid(uint32_t address);\n+void jump_to_app(uint32_t address);\n+\n+#include \"boot_uart_ota.h\"\n+\n+/* Host 模拟 Flash (32KB 测试窗口映射 0x08020000 起) 与串口/复位状态 */\n+#define SIM_FLASH_SIZE            (32U * 1024U)\n+static uint8_t s_sim_flash[SIM_FLASH_SIZE];\n+static uint32_t s_erase_count = 0U;\n+static uint32_t s_sim_magic = 0U;\n+static uint32_t s_sim_systick = 1234U;\n+static uint32_t s_reset_count = 0U;\n+static uint32_t s_jump_count = 0U;\n+static uint32_t s_last_jump_addr = 0U;\n+static uint8_t s_last_tx[MINIMC_MAX_FRAME_SIZE];\n+static uint16_t s_last_tx_len = 0U;\n+\n+/**\n+  * @brief  断言辅助函数：条件为假时打印错误并退出\n+  */\n+static void require_true(int cond, const char *msg)\n+{\n+  if (!cond)\n+  {\n+    fprintf(stderr, \"[FAIL] %s\\n\", msg);\n+    exit(1);\n+  }\n+}\n+\n+/**\n+  * @brief  返回模拟系统毫秒计数\n+  */\n+uint32_t host_mock_get_systick_ms(void)\n+{\n+  return s_sim_systick;\n+}\n+\n+/**\n+  * @brief  模拟擦除一个 2KB Flash 扇区\n+  */\n+int host_mock_flash_erase_sector(uint32_t sector_addr)\n+{\n+  if (sector_addr < FLASH_APP_ADDR ||\n+      (sector_addr - FLASH_APP_ADDR + MC_FLASH_SECTOR_SIZE) > SIM_FLASH_SIZE)\n+  {\n+    return -1;\n+  }\n+  memset(&s_sim_flash[sector_addr - FLASH_APP_ADDR], 0xFF, MC_FLASH_SECTOR_SIZE);\n+  s_erase_count++;\n+  return 0;\n+}\n+\n+/**\n+  * @brief  模拟向 Flash 写入字节并执行 AND 编程与回读校验\n+  */\n+int host_mock_flash_write_bytes(uint32_t addr, const uint8_t *p_data, uint32_t len)\n+{\n+  if (addr < FLASH_APP_ADDR || (addr - FLASH_APP_ADDR + len) > SIM_FLASH_SIZE)\n+  {\n+    return -1;\n+  }\n+  uint32_t off = addr - FLASH_APP_ADDR;\n+  for (uint32_t i = 0U; i < len; i++)\n+  {\n+    s_sim_flash[off + i] &= p_data[i];\n+    if (s_sim_flash[off + i] != p_data[i])\n+    {\n+      return -2;\n+    }\n+  }\n+  return 0;\n+}\n+\n+/**\n+  * @brief  获取模拟 Flash 指针\n+  */\n+const uint8_t *host_mock_flash_ptr(uint32_t addr)\n+{\n+  return &s_sim_flash[addr - FLASH_APP_ADDR];\n+}\n+\n+/**\n+  * @brief  捕获 USART2 发送的响应帧\n+  */\n+void host_mock_uart2_send_bytes(const uint8_t *p_data, uint16_t len)\n+{\n+  if (len <= sizeof(s_last_tx))\n+  {\n+    memcpy(s_last_tx, p_data, len);\n+    s_last_tx_len = len;\n+  }\n+}\n+\n+/**\n+  * @brief  读取模拟 SRAM 顶部 UPG2 魔数\n+  */\n+uint32_t host_mock_read_magic(void)\n+{\n+  return s_sim_magic;\n+}\n+\n+/**\n+  * @brief  写入模拟 SRAM 顶部 UPG2 魔数\n+  */\n+void host_mock_write_magic(uint32_t val)\n+{\n+  s_sim_magic = val;\n+}\n+\n+/**\n+  * @brief  模拟 NVIC_SystemReset\n+  */\n+void host_mock_system_reset(void)\n+{\n+  s_reset_count++;\n+}\n+\n+/**\n+  * @brief  模拟 jump_to_app\n+  */\n+void host_mock_jump_to_app(uint32_t addr)\n+{\n+  s_jump_count++;\n+  s_last_jump_addr = addr;\n+}\n+\n+/**\n+  * @brief  校验模拟 Flash 首地址处的 MSP 与 Reset_Handler 向量合法性\n+  */\n+uint8_t is_app_valid(uint32_t address)\n+{\n+  const uint8_t *p = host_mock_flash_ptr(address);\n+  uint32_t msp = 0U;\n+  uint32_t pc = 0U;\n+  memcpy(&msp, &p[0], 4U);\n+  memcpy(&pc, &p[4], 4U);\n+  if (msp < 0x20001000U || msp > 0x20060000U)\n+  {\n+    return 0U;\n+  }\n+  if (pc < 0x08020000U || pc > 0x08100000U || (pc & 1U) == 0U)\n+  {\n+    return 0U;\n+  }\n+  return 1U;\n+}\n+\n+#include \"../bootloader/src/boot_uart_ota.c\"\n+\n+/**\n+  * @brief  构造并向 USART2 接收状态机注入一帧 MiniMCProto v2.0 报文\n+  */\n+static void send_minimc_frame(uint8_t dst,\n+                              uint8_t cmd,\n+                              uint16_t seq,\n+                              const void *p_payload)\n+{\n+  minimc_frame_hdr_t hdr;\n+  uint16_t len = 0U;\n+  if (cmd == MINIMC_CMD_PING || cmd == MINIMC_CMD_SYSTEM_CONTROL) { len = 4U; }\n+  else if (cmd == MINIMC_CMD_OTA_START) { len = 144U; }\n+  else if (cmd == MINIMC_CMD_OTA_FINISH) { len = 8U; }\n+\n+  hdr.sof0 = MINIMC_SOF_0;\n+  hdr.sof1 = MINIMC_SOF_1;\n+  hdr.src_id = MINIMC_NODE_AP;\n+  hdr.dst_id = dst;\n+  hdr.flags = (uint8_t)(MINIMC_FLAG_VERSION_V2 | MINIMC_FLAG_WANTS_ACK);\n+  hdr.cmd_id = cmd;\n+  hdr.hop_limit = MINIMC_DEFAULT_HOP_LIMIT;\n+  hdr.route_ctrl = 0U;\n+  hdr.seq_id = seq;\n+  hdr.payload_len = len;\n+\n+  uint8_t raw[MINIMC_MAX_FRAME_SIZE];\n+  memcpy(raw, &hdr, MINIMC_HEADER_SIZE);\n+  if (len > 0U && p_payload != NULL)\n+  {\n+    memcpy(&raw[MINIMC_HEADER_SIZE], p_payload, len);\n+  }\n+  uint16_t crc = boot_crc16_ccitt(raw, (uint32_t)(MINIMC_HEADER_SIZE + len));\n+  raw[MINIMC_HEADER_SIZE + len] = (uint8_t)(crc & 0xFFU);\n+  raw[MINIMC_HEADER_SIZE + len + 1U] = (uint8_t)((crc >> 8U) & 0xFFU);\n+\n+  s_last_tx_len = 0U;\n+  for (uint16_t i = 0U; i < (uint16_t)(MINIMC_FRAME_OVERHEAD + len); i++)\n+  {\n+    boot_uart_ota_rx_byte_isr(raw[i]);\n+  }\n+  boot_uart_ota_poll();\n+}\n+\n+/**\n+  * @brief  发送 512B 分块的 0x21 CMD_OTA_DATA 数据帧\n+  */\n+static void send_ota_data_chunk(uint16_t seq,\n+                                uint32_t offset,\n+                                const uint8_t *p_data)\n+{\n+  uint16_t data_len = 512U;\n+  uint16_t pay_len = (uint16_t)(sizeof(minimc_payload_ota_data_hdr_t) + data_len);\n+  minimc_frame_hdr_t hdr = {\n+    MINIMC_SOF_0, MINIMC_SOF_1, MINIMC_NODE_AP, MINIMC_NODE_MC,\n+    (uint8_t)(MINIMC_FLAG_VERSION_V2 | MINIMC_FLAG_WANTS_ACK),\n+    MINIMC_CMD_OTA_DATA, MINIMC_DEFAULT_HOP_LIMIT, 0U, seq, pay_len\n+  };\n+  minimc_payload_ota_data_hdr_t dh;\n+  dh.offset = offset;\n+  dh.chunk_bytes = data_len;\n+  dh.chunk_crc16 = boot_crc16_ccitt(p_data, data_len);\n+\n+  uint8_t raw[MINIMC_MAX_FRAME_SIZE];\n+  memcpy(raw, &hdr, MINIMC_HEADER_SIZE);\n+  memcpy(&raw[MINIMC_HEADER_SIZE], &dh, sizeof(dh));\n+  memcpy(&raw[MINIMC_HEADER_SIZE + sizeof(dh)], p_data, data_len);\n+  uint16_t crc = boot_crc16_ccitt(raw, (uint32_t)(MINIMC_HEADER_SIZE + pay_len));\n+  raw[MINIMC_HEADER_SIZE + pay_len] = (uint8_t)(crc & 0xFFU);\n+  raw[MINIMC_HEADER_SIZE + pay_len + 1U] = (uint8_t)((crc >> 8U) & 0xFFU);\n+\n+  s_last_tx_len = 0U;\n+  for (uint16_t i = 0U; i < (uint16_t)(MINIMC_FRAME_OVERHEAD + pay_len); i++)\n+  {\n+    boot_uart_ota_rx_byte_isr(raw[i]);\n+  }\n+  boot_uart_ota_poll();\n+}\n+\n+/**\n+  * @brief  生成合法测试镜像与 128B ATSG Trailer\n+  */\n+static void build_mc_image_and_trailer(uint8_t *p_img,\n+                                       uint32_t len,\n+                                       fw_trailer_t *p_tr,\n+                                       uint32_t *p_crc)\n+{\n+  for (uint32_t i = 0U; i < len; i++)\n+  {\n+    p_img[i] = (uint8_t)((i * 37U + 11U) & 0xFFU);\n+  }\n+  uint32_t msp = 0x20040000UL;\n+  uint32_t pc = 0x08020101UL;\n+  memcpy(&p_img[0], &msp, 4U);\n+  memcpy(&p_img[4], &pc, 4U);\n+\n+  memset(p_tr, 0, sizeof(*p_tr));\n+  p_tr->magic = TRAILER_MAGIC_ATSG;\n+  p_tr->struct_ver = TRAILER_STRUCT_VER_V1;\n+  p_tr->board_id = BOARD_ID_MC_AT32F435;\n+  p_tr->fw_version = 0x01020300UL;\n+  p_tr->payload_len = len;\n+  p_tr->trailer_crc32 = boot_crc32_ieee((const uint8_t *)p_tr, TRAILER_HEADER_CRC_SIZE);\n+  *p_crc = boot_crc32_ieee(p_img, len);\n+}\n+\n+/**\n+  * @brief  测试 UPG2 驻留魔数、0x01/0x02、0x03/0x04、0x1D 及 DST=0x03 严格静默丢弃\n+  */\n+static void test_magic_info_heartbeat_and_dst_filter(void)\n+{\n+  s_sim_magic = BOOT_MC_UPGRADE_MAGIC_VAL;\n+  boot_uart_ota_init();\n+  require_true(s_sim_magic == 0UL, \"UPG2 magic must be cleared on init\");\n+  require_true(boot_uart_ota_should_stay_in_boot() == 1U, \"UPG2 magic sets stay_in_boot\");\n+  uint32_t bid1 = boot_uart_ota_get_boot_id();\n+\n+  boot_uart_ota_init();\n+  uint32_t bid2 = boot_uart_ota_get_boot_id();\n+  require_true(bid1 != 0U && bid2 != 0U && bid1 != bid2, \"dynamic boot_id changes across init\");\n+\n+  /* DST=0x03 (TH) 必须静默忽略，零字节发送 */\n+  send_minimc_frame(MINIMC_NODE_TH, MINIMC_CMD_GET_VERSION, 1U, NULL);\n+  require_true(s_last_tx_len == 0U, \"DST=0x03 must be ignored by MC Bootloader\");\n+\n+  /* 0x01 -> 0x02 CMD_VERSION_REPORT */\n+  send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_GET_VERSION, 2U, NULL);\n+  require_true(s_last_tx_len == 30U && s_last_tx[5] == MINIMC_CMD_VERSION_REPORT, \"0x02 VERSION_REPORT\");\n+  minimc_payload_version_report_t vrep;\n+  memcpy(&vrep, &s_last_tx[12], sizeof(vrep));\n+  require_true(vrep.capability_flags == MC_BOOT_CAPABILITY_FLAGS && vrep.boot_id == bid2, \"MC capability_flags == 0xC0080435\");\n+\n+  /* 0x03 -> 0x04 CMD_PONG */\n+  uint32_t tok = 0xCAFEBABEUL;\n+  send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_PING, 3U, &tok);\n+  require_true(s_last_tx_len == 26U && s_last_tx[5] == MINIMC_CMD_PONG, \"0x04 PONG\");\n+\n+  /* 0x1D JumpToBootloader(2) & Reboot(1) */\n+  minimc_payload_sys_ctrl_t sc_boot = {2U, 1U, 10U};\n+  send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_SYSTEM_CONTROL, 4U, &sc_boot);\n+  require_true(s_last_tx[5] == MINIMC_CMD_ACK && boot_uart_ota_should_stay_in_boot() == 1U, \"0x1D stay in boot\");\n+  minimc_payload_sys_ctrl_t sc_reboot = {1U, 1U, 10U};\n+  send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_SYSTEM_CONTROL, 5U, &sc_reboot);\n+  require_true(s_last_tx[5] == MINIMC_CMD_ACK && s_reset_count == 1U, \"0x1D reboot\");\n+}\n+\n+/**\n+  * @brief  测试单写者互斥锁 (USB Host vs USART2) 与 0x20 擦除前零擦除负例门禁及恢复\n+  */\n+static void test_single_writer_mutex_and_zero_erase_admission(void)\n+{\n+  uint8_t img[1024];\n+  fw_trailer_t tr;\n+  uint32_t crc = 0U;\n+  build_mc_image_and_trailer(img, sizeof(img), &tr, &crc);\n+  boot_uart_ota_init();\n+  s_erase_count = 0U;\n+\n+  minimc_payload_ota_start_t req;\n+  memset(&req, 0, sizeof(req));\n+  req.target_device = MINIMC_NODE_MC;\n+  req.target_component = 1U;\n+  req.fw_size_bytes = sizeof(img);\n+  req.fw_crc32 = crc;\n+  req.trailer = tr;\n+\n+  /* 1. USB 升级占用时，USART2 0x20 必须返回 NACK 0x05 (DEVICE_BUSY) 且零擦除 */\n+  g_upgrade_in_progress = 1U;\n+  send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_OTA_START, 10U, &req);\n+  require_true(s_last_tx[5] == MINIMC_CMD_NACK && s_last_tx[12] == MINIMC_ERR_DEVICE_BUSY, \"USB busy -> NACK 0x05\");\n+  require_true(s_erase_count == 0U, \"USB busy zero erase\");\n+  g_upgrade_in_progress = 0U;\n+\n+  /* 2. 917,505B (896KB + 1B) 超限必须返回 NACK 0x14 (OTA_IMAGE_OVERSIZE) 且零擦除 */\n+  req.fw_size_bytes = MC_MAX_APP_SIZE + 1U;\n+  req.trailer = tr;\n+  req.trailer.payload_len = MC_MAX_APP_SIZE + 1U;\n+  send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_OTA_START, 11U, &req);\n+  require_true(s_last_tx[5] == MINIMC_CMD_NACK && s_last_tx[12] == MINIMC_ERR_OTA_IMAGE_OVERSIZE && s_erase_count == 0U, \"oversize 917505B zero erase\");\n+\n+  /* 3. 错板 (TH 0x42300001) 与坏 trailer_crc32 必须返回 NACK 0x06 且零擦除，且状态保持 IDLE 并可恢复 */\n+  req.fw_size_bytes = sizeof(img);\n+  req.trailer = tr;\n+  req.trailer.board_id = BOARD_ID_TH_AT32F423;\n+  req.trailer.trailer_crc32 = boot_crc32_ieee((const uint8_t *)&req.trailer, TRAILER_HEADER_CRC_SIZE);\n+  send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_OTA_START, 12U, &req);\n+  require_true(s_last_tx[5] == MINIMC_CMD_NACK && s_last_tx[12] == MINIMC_ERR_COMMAND_