railer, BOARD_ID_MC_AT32F435, MC_MAX_APP_SIZE) != 0)\n  {\n    boot_ota_release_writer(BOOT_WRITER_UART2);\n    send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);\n    return;\n  }\n\n  s_ota.stay_in_boot = 1U;\n  s_ota.state = MC_OTA_STATE_ERASED_READY;\n  s_ota.last_error = 0U;\n  s_ota.expected_size = req.fw_size_bytes;\n  s_ota.expected_crc32 = req.fw_crc32;\n  s_ota.next_offset = 0U;\n  s_ota.erased_end_addr = FLASH_APP_ADDR;\n  send_ack(p_req);\n}\n\n/**\n  * @brief  按需擦除 2KB 扇区并向 MC App 分区写入与回读校验数据块\n  */\nstatic int write_mc_app_flash_chunk(uint32_t offset,\n                                    const uint8_t *p_data,\n                                    uint32_t data_len)\n{\n  uint32_t target_addr = FLASH_APP_ADDR + offset;\n  uint32_t end_addr = target_addr + data_len;\n\n#ifndef HOST_UNIT_TEST\n  flash_unlock();\n  while (s_ota.erased_end_addr < end_addr)\n  {\n    if (flash_sector_erase(s_ota.erased_end_addr) != FLASH_OPERATE_DONE)\n    {\n      flash_lock();\n      return -1;\n    }\n    s_ota.erased_end_addr += MC_FLASH_SECTOR_SIZE;\n  }\n  for (uint32_t i = 0U; i < data_len; i++)\n  {\n    if (flash_byte_program(target_addr + i, p_data[i]) != FLASH_OPERATE_DONE ||\n        *(volatile uint8_t *)(target_addr + i) != p_data[i])\n    {\n      flash_lock();\n      return -2;\n    }\n  }\n  flash_lock();\n  return 0;\n#else\n  while (s_ota.erased_end_addr < end_addr)\n  {\n    if (host_mock_flash_erase_sector(s_ota.erased_end_addr) != 0)\n    {\n      return -1;\n    }\n    s_ota.erased_end_addr += MC_FLASH_SECTOR_SIZE;\n  }\n  return host_mock_flash_write_bytes(target_addr, p_data, data_len);\n#endif\n}\n\n/**\n  * @brief  校验 0x21 CMD_OTA_DATA 的块长度、偏移边界与内层 CRC16\n  */\nstatic uint8_t validate_ota_data_bounds(const minimc_frame_hdr_t *p_req,\n                                        const uint8_t *p_payload,\n                                        minimc_payload_ota_data_hdr_t *p_dh)\n{\n  if (s_ota.state != MC_OTA_STATE_ERASED_READY && s_ota.state != MC_OTA_STATE_FLASH_WRITING)\n  {\n    return MINIMC_ERR_COMMAND_REJECTED;\n  }\n  if (p_payload == NULL || p_req->payload_len <= sizeof(minimc_payload_ota_data_hdr_t))\n  {\n    return MINIMC_ERR_COMMAND_REJECTED;\n  }\n  memcpy(p_dh, p_payload, sizeof(*p_dh));\n  uint16_t data_len = (uint16_t)(p_req->payload_len - sizeof(*p_dh));\n  if (p_dh->chunk_bytes == 0U || p_dh->chunk_bytes > CHUNK_MAX_SIZE || p_dh->chunk_bytes != data_len)\n  {\n    return MINIMC_ERR_MTU_EXCEEDED;\n  }\n  if (p_dh->offset > s_ota.expected_size || (uint32_t)data_len > (s_ota.expected_size - p_dh->offset))\n  {\n    return MINIMC_ERR_OTA_INVALID_OFFSET;\n  }\n  const uint8_t *p_data = &p_payload[sizeof(*p_dh)];\n  if (boot_crc16_ccitt(p_data, data_len) != p_dh->chunk_crc16)\n  {\n    return MINIMC_ERR_CRC_FAIL;\n  }\n  return 0U;\n}\n\n/**\n  * @brief  处理 0x21 CMD_OTA_DATA (支持重传幂等与按扇区擦写回读校验)\n  */\nstatic void handle_cmd_ota_data(const minimc_frame_hdr_t *p_req,\n                                const uint8_t *p_payload)\n{\n  minimc_payload_ota_data_hdr_t dh;\n  uint8_t err = validate_ota_data_bounds(p_req, p_payload, &dh);\n  if (err != 0U)\n  {\n    send_nack(p_req, err);\n    return;\n  }\n\n  /* 重传幂等：已写入块重传直接回复 ACK */\n  if (dh.offset < s_ota.next_offset && (dh.offset + dh.chunk_bytes) <= s_ota.next_offset)\n  {\n    send_ack(p_req);\n    return;\n  }\n  if (dh.offset != s_ota.next_offset)\n  {\n    send_nack(p_req, MINIMC_ERR_OTA_INVALID_OFFSET);\n    return;\n  }\n\n  const uint8_t *p_data = &p_payload[sizeof(dh)];\n  int wrc = write_mc_app_flash_chunk(dh.offset, p_data, dh.chunk_bytes);\n  if (wrc != 0)\n  {\n    s_ota.state = MC_OTA_STATE_ERROR;\n    send_nack(p_req, (wrc == -1) ? MINIMC_ERR_OTA_ERASE_FAIL : MINIMC_ERR_OTA_WRITE_FAIL);\n    return;\n  }\n\n  s_ota.state = MC_OTA_STATE_FLASH_WRITING;\n  s_ota.next_offset += dh.chunk_bytes;\n  send_ack(p_req);\n}\n\n/**\n  * @brief  处理 0x23 CMD_OTA_STATUS 请求并回复 8B 进度状态\n  */\nstatic void handle_cmd_ota_status(const minimc_frame_hdr_t *p_req)\n{\n  if (p_req->payload_len != 0U)\n  {\n    send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);\n    return;\n  }\n  minimc_payload_ota_status_t rsp;\n  rsp.ota_state = (uint8_t)s_ota.state;\n  rsp.error_code = s_ota.last_error;\n  rsp.cached_chunk0_bytes = 0U;\n  rsp.bytes_written = s_ota.next_offset;\n  send_minimc_response(p_req, MINIMC_CMD_OTA_STATUS, (const uint8_t *)&rsp, sizeof(rsp));\n}\n\n/**\n  * @brief  处理 0x22 CMD_OTA_FINISH (全镜像 IEEE CRC32 校验与安全跳转准备)\n  */\nstatic void handle_cmd_ota_finish(const minimc_frame_hdr_t *p_req,\n                                  const uint8_t *p_payload)\n{\n  if (p_payload == NULL || p_req->payload_len != sizeof(minimc_payload_ota_finish_t))\n  {\n    send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);\n    return;\n  }\n  minimc_payload_ota_finish_t fin;\n  memcpy(&fin, p_payload, sizeof(fin));\n\n  if (s_ota.state == MC_OTA_STATE_VERIFIED_COMMITTED && fin.fw_crc32 == s_ota.expected_crc32)\n  {\n    send_ack(p_req);\n    return;\n  }\n  if (s_ota.next_offset != s_ota.expected_size || s_ota.expected_size == 0U)\n  {\n    send_nack(p_req, MINIMC_ERR_OTA_INVALID_OFFSET);\n    return;\n  }\n\n#ifndef HOST_UNIT_TEST\n  const uint8_t *p_flash = (const uint8_t *)FLASH_APP_ADDR;\n#else\n  const uint8_t *p_flash = host_mock_flash_ptr(FLASH_APP_ADDR);\n#endif\n  uint32_t calc_crc = boot_crc32_ieee(p_flash, s_ota.expected_size);\n  if (calc_crc != s_ota.expected_crc32 || calc_crc != fin.fw_crc32 || is_app_valid(FLASH_APP_ADDR) == 0U)\n  {\n    s_ota.state = MC_OTA_STATE_ERROR;\n    send_nack(p_req, MINIMC_ERR_OTA_CRC_MISMATCH);\n    return;\n  }\n\n  s_ota.state = MC_OTA_STATE_VERIFIED_COMMITTED;\n  boot_ota_release_writer(BOOT_WRITER_UART2);\n  send_ack(p_req);\n  if (fin.action_after_verify == 1U)\n  {\n    s_ota.pending_jump = 1U;\n  }\n}\n\n/**\n  * @brief  分发一帧已通过外层 CRC16 校验的 MiniMCProto v2.0 报文\n  */\nstatic void dispatch_valid_frame(const minimc_frame_hdr_t *p_hdr, const uint8_t *p_payload)\n{\n  /* 严格节点过滤：仅处理发往 MC(0x02) 的 V2 请求帧，绝不响应或转发 DST=0x03(TH) */\n  if (p_hdr->dst_id != MINIMC_NODE_MC)\n  {\n    return;\n  }\n  if ((p_hdr->flags & 0x0CU) != MINIMC_FLAG_VERSION_V2 ||\n      (p_hdr->flags & MINIMC_FLAG_IS_RESPONSE) != 0U)\n  {\n    return;\n  }\n\n  s_ota.rx_ok_count++;\n  switch (p_hdr->cmd_id)\n  {\n    case MINIMC_CMD_GET_VERSION:    handle_cmd_get_version(p_hdr); break;\n    case MINIMC_CMD_PING:           handle_cmd_ping(p_hdr, p_payload); break;\n\n  /* 步骤 2: 恢复为 USB 复用功能 MUX10 */\n  gpio_default_para_init(&gpio_init_struct);\n  gpio_init_struct.gpio_mode = GPIO_MODE_MUX;\n  gpio_init(OTG_PIN_GPIO, &gpio_init_struct);\n\n  gpio_pin_mux_config(OTG_PIN_GPIO, OTG_PIN_DP_SOURCE, OTG_PIN_MUX);\n  gpio_pin_mux_config(OTG_PIN_GPIO, OTG_PIN_DM_SOURCE, OTG_PIN_MUX);\n}\n\nstatic void handle_no_disk_timeout(uint32_t ticks) {\n  if (is_app_valid(FLASH_APP_ADDR)) {\n    printf(\"Probe timeout. Valid App found at 0x%08X.\\r\\n\", FLASH_APP_ADDR);\n    printf(\"Jumping to application...\\r\\n\");\n    jump_to_app(FLASH_APP_ADDR);\n  } else {\n    /* 未找到有效 App 且无 U 盘时，每隔 1000ms (1 秒) 周期输出提示 */\n    if ((ticks % 1000U) == 0U) {\n      printf(\"No valid App at 0x%08X. Waiting for U-disk...\\r\\n\",\n             FLASH_APP_ADDR);\n    }\n  }\n}\n\nstatic void eeprom_startup_probe(void) {\n  uint8_t test_val = 0U;\n  eeprom_status_t status;\n\n  bsp_eeprom_init();\n  status = bsp_eeprom_read_byte(0x00U, &test_val);\n\n  if (status == EEPROM_OK) {\n    printf(\"[EEPROM] I2C2 PB10/PB11 @ 100K (Addr: 0xA0) -> SUCCESS! Byte[0x00] = 0x%02X\\r\\n\", test_val);\n    bsp_eeprom_dump(0x00U, 256U);\n  } else {\n    printf(\"[EEPROM] I2C2 PB10/PB11 @ 100K (Addr: 0xA0) -> FAILED (Status: %d)\\r\\n\", (int)status);\n  }\n}\n\n/**\n  * @brief  初始化 USB Host OTG 控制器与 48MHz HICK 时钟源\n  */\nstatic void usb_host_init_hardware(void) {\n  uint32_t hick_timeout = 1000000U;\n\n  usb_gpio_config();\n  crm_periph_clock_enable(OTG_CLOCK, TRUE);\n  crm_clock_source_enable(CRM_CLOCK_SOURCE_HICK, TRUE);\n  while (crm_flag_get(CRM_HICK_STABLE_FLAG) != SET && --hick_timeout > 0U) {\n  }\n  crm_usb_clock_source_select(CRM_USB_CLOCK_SOURCE_HICK);\n  nvic_irq_enable(OTG_IRQ, 0, 0);\n  usbh_init(&otg_core_struct, USB_FULL_SPEED_CORE_ID, USB_ID,\n            &uhost_msc_class_handler, &usbh_user_handle);\n  delay_ms(200U);\n}\n\nint main(void) {\n  nvic_priority_group_config(NVIC_PRIORITY_GROUP_4);\n  system_clock_config();\n  timebase_init();\n  uart_print_init(115200);\n  boot_uart_ota_init();\n\n  printf(\"\\r\\n========================================\\r\\n\");\n  printf(\"  AT32F435 U-Disk + UART2 Bootloader (\" __DATE__ \" \" __TIME__ \" | Build #%lu)\\r\\n\",\n         (uint32_t)BOOTLOADER_BUILD_NUMBER);\n  printf(\"  Flash: 1024KB | Bl: 128KB | App: 0x08020000\\r\\n\");\n  printf(\"========================================\\r\\n\");\n\n  eeprom_startup_probe();\n  usb_host_init_hardware();\n  printf(\"Probing for U-disk / UART2 OTA (2.0s timeout window)...\\r\\n\");\n\n  uint32_t last_tick = get_systick_ms();\n  uint32_t probe_ticks = 0U;\n\n  while (1) {\n    boot_uart_ota_poll();\n    usbh_loop_handler(&otg_core_struct.host);\n    if (g_upgrade_in_progress || boot_uart_ota_should_stay_in_boot() != 0U) {\n      continue;\n    }\n\n    uint32_t now = get_systick_ms();\n    if (now != last_tick) {\n      probe_ticks += (now - last_tick);\n      last_tick = now;\n      if (probe_ticks >= 2000U && !g_udisk_connected) {\n        handle_no_disk_timeout(probe_ticks);\n      }\n    }\n  }\n}\n/tmp/qa_sandboxes/TWIN-63_run_110942_20261106_030942/boot/bootloadermc/bootloader/inc/boot_uart_ota.h:3:  * @file     boot_uart_ota.h\n/tmp/qa_sandboxes/TWIN-63_run_110942_20261106_030942/boot/bootloadermc/bootloader/inc/boot_uart_ota.h:306:void boot_uart_ota_init(void);\n/tmp/qa_sandboxes/TWIN-63_run_110942_20261106_030942/boot/bootloadermc/bootloader/inc/boot_uart_ota.h:311:void boot_uart_ota_deinit(void);\n/tmp/qa_sandboxes/TWIN-63_run_110942_20261106_030942/boot/bootloadermc/bootloader/inc/boot_uart_ota.h:316:vo